select v.mk, (extract(epoch from time_bucket('10 seconds', t.event_time))*1000)::bigint b,
  (array_agg(t.price order by t.event_time, t.trade_id_num nulls last, t.trade_id))[1] o,
  max(t.price) h, min(t.price) l,
  (array_agg(t.price order by t.event_time desc, t.trade_id_num desc nulls last, t.trade_id desc))[1] c,
  count(*) filter (where t.taker_side='buy') cb, count(*) filter (where t.taker_side='sell') cs,
  coalesce(sum(t.price*t.qty) filter (where t.taker_side='buy'),0) vb, coalesce(sum(t.price*t.qty) filter (where t.taker_side='sell'),0) vs
from v join md.trades t on t.exchange=v.exchange and t.market=v.market and t.symbol=v.symbol and t.event_time >= v.m and t.event_time < v.m + interval '1 minute'
group by 1,2 order by 1,2;
